using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Apollonian;

internal sealed class InnerFaceStagesDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Apollonian/InnerFaceStages.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/Eigenstructure/radsararanando2026apollonian");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The deterministic finite inner-face Apollonian stages and their source-derived combinatorial laws.",
        H("Inner-face Apollonian stages"),
        Blocks(
            Node("Face", "Inner faces",
                "For every natural stage n, Face 0 is Fin 3 and Face (n+1) is Face n × Fin 3. The child label records the omitted old corner. This index contains only the inner faces; it does not contain the outer triangle.", DescribeRole.Definition),
            Node("Vertex", "Persistent vertices",
                "Vertex 0 is Fin 4. Vertex (n+1) is the disjoint sum Vertex n ⊕ Face n. An inl vertex is retained, and inr f is the one distinct vertex inserted into inner face f.", DescribeRole.Definition),
            Node("corner", "Ordered corners",
                "Seed vertices 0,1,2,3 are a,b,c,o. Face f at stage zero has corners (3,f,f+1 modulo 3), with the outer indices included in Fin 4. For child (f,i), corner i is inr f and every other corner j is inl (corner n f j). Thus exactly one centre and two retained corners bound each child triangle.", DescribeRole.Definition),
            Node("Incident", "Corner incidence",
                "Incident n f v means there exists an index i in Fin 3 with corner n f i = v. It refers to the actual ordered triangle of f.", DescribeRole.Definition),
            Node("adjacent", "Exact adjacency recursion",
                "At stage zero, two seed vertices are adjacent exactly when distinct. At a successor stage, old-old adjacency is exactly previous adjacency; old-new adjacency means that the old endpoint is a corner of the new endpoint’s parent face. New-new adjacency is false. The relation is symmetric and irreflexive.", DescribeRole.Definition),
            Node("graph", "The finite simple stage graph",
                "For every natural n, graph n is the simple unweighted graph on Vertex n with the recursively constructed adjacency. Both the vertex and inner-face types carry finite enumerations and decidable equality. Every subdivision is simultaneous over all indexed inner faces.", DescribeRole.Definition),
            Node("faceCount", "Incident inner-face count",
                "For n and v in Vertex n, faceCount n v is the sum over f in Face n of one when Incident n f v holds and zero otherwise. It counts only current inner faces.", DescribeRole.Definition),
            Node("pairFaceCount", "Pair incidence count",
                "For n and u,v in Vertex n, pairFaceCount n u v counts current inner faces containing both u and v. It is not the number of all graph common neighbours.", DescribeRole.Definition),
            Node("degreeCount", "Adjacency row count",
                "For n and v in Vertex n, degreeCount n v is the sum over all u in Vertex n of the zero-one indicator of actual adjacency from v to u.", DescribeRole.Definition),
            Node("faceCount_old", "Incident faces of a retained vertex",
                "For every natural n and v in Vertex n, faceCount (n+1) (inl v) = 2*faceCount n v. Each incident parent face gives exactly two incident children.", DescribeRole.Theorem),
            Node("faceCount_new", "Incident faces at insertion",
                "For every natural n and current inner face f, the vertex inr f at stage n+1 belongs to exactly three inner child faces.", DescribeRole.Theorem),
            Node("seed_injective", "Distinct persistent seed vertices",
                "For every natural n the map seed n from Fin 4 to Vertex n is injective.", DescribeRole.Theorem),
            Node("degreeCount_old", "Degree increment of a retained vertex",
                "For every natural n and v in Vertex n, degreeCount (n+1) (inl v) = degreeCount n v + faceCount n v. The retained vertex acquires exactly one neighbour from each currently incident inner face.", DescribeRole.Theorem),
            Node("inner_faces_distinct", "Inner-face indices do not duplicate triangles",
                "For every n and f,g in Face n, if Incident n f v is equivalent to Incident n g v for every v in Vertex n, then f=g. At a successor stage the unique new corner determines the parent; injectivity of the parent corner triple then determines the omitted corner.", DescribeRole.Theorem),
            Node("embed", "Canonical stage inclusion",
                "For n,t natural and v in Vertex n, embed n 0 v is v and embed n (t+1) v is inl (embed n t v), lying in Vertex (n+t+1). Thus the same persistent vertex is identified at all later stages.", DescribeRole.Definition),
            Node("birth", "Actual insertion stage",
                "The four seed vertices have birth zero. A retained vertex keeps its birth, and inr f at stage n+1 has birth n+1. Every vertex at stage n has birth at most n.", DescribeRole.Definition),
            Node("adjacent_embed", "Adjacency persists exactly",
                "For all natural n,t and u,v in Vertex n, adjacency of embed n t u and embed n t v in stage n+t is equivalent to adjacency of u and v in stage n. There are no later edges between two old vertices.", DescribeRole.Theorem),
            Node("old_vertices_iff", "The cutoff partition is the actual birth partition",
                "For all natural k,t and w in Vertex (k+t), birth (k+t) w ≤ k if and only if there exists u in Vertex k with embed k t u = w. The canonical inclusion is injective, so old vertices have unique representatives.", DescribeRole.Theorem),
            Node("degreeCount_inner", "Exact degree of every inserted vertex",
                "For every n, v in Vertex n, and positive birth j=birth n v, degreeCount n v = 3·2^(n−j). The new vertex starts with three neighbours and three inner incident faces; each subsequent subdivision doubles its incident-face count and adds that many neighbours. Natural subtraction is used, with j≤n proved from the constructor.", DescribeRole.Theorem),
            Node("degreeCount_late_le", "Uniform degree bound after a cutoff",
                "For all natural n,k and v in Vertex n satisfying k < birth n v, degreeCount n v ≤ 3·2^(n−k−1). This is derived from the exact birth-degree law and monotonicity of the natural power, without a degree assumption.", DescribeRole.Theorem),
            Node("seed", "The labelled seed vertices",
                "For every n, seed n includes Fin 4 in Vertex n by iterating inl. Indices 0,1,2 give the distinguished outer triangle, and index 3 is the original centre.", DescribeRole.Definition),
            Node("seed_degrees", "Exact seed degrees at every stage",
                "For every natural n and v in Fin 4, degreeCount n (seed n v) is 3·2^n when v=3 and 2^(n+1)+1 otherwise. These are precisely the centre and the three outer vertices. The arbitrary-stage induction includes the initial face and degree computations and sums the constructor’s incident-face increments; the source’s displayed degrees are not premises.", DescribeRole.Theorem),
            Node("degreeCount_eq_degree", "The count is the ordinary graph degree",
                "For every n and v in Vertex n, degreeCount n v equals (graph n).degree v. Thus all the stated degree counts refer to the same simple graph used for ordinary adjacency.", DescribeRole.Theorem),
            Node("card_vertex_ge_four", "A second eigenvalue index is available",
                "For every natural n, 4 ≤ Fintype.card (Vertex n). The four seed vertices remain distinct. No closed formula for the total number of vertices is needed or asserted.", DescribeRole.Theorem),
            Node("lateCommonCount", "Actual late common neighbours",
                "For k,t natural and u,v in Vertex k, lateCommonCount k t u v counts w in Vertex (k+t) satisfying k < birth (k+t) w and adjacency to both embed k t u and embed k t v. It counts vertices of the actual graph, including the diagonal case u=v.", DescribeRole.Definition),
            Node("Oriented", "Orientation by birth",
                "Oriented n u v means actual adjacency together with birth n v < birth n u. The directed edge runs from the newer endpoint to the older endpoint.", DescribeRole.Definition),
            Node("oriented_outdegree_le_three", "At most three older neighbours",
                "For every n and u in Vertex n, the number of v with Oriented n u v is at most three. Seed-to-seed edges have equal birth and receive no birth orientation. Inserted vertices have exactly their three parent corners as older neighbours; later subdivisions preserve those edges and add only younger neighbours.", DescribeRole.Theorem),
            Node("late_edge_oriented", "Every edge of the late induced graph is oriented",
                "For all natural n,k and u,v in Vertex n with both births greater than k and with u adjacent to v, Oriented n u v or Oriented n v u holds. Distinct inserted vertices in one generation are never adjacent. Hence an edge of the late induced graph has unequal endpoint births.", DescribeRole.Theorem),
            Node("late_oriented_indegree_le", "Indegree bound in the late graph",
                "For n,k and u in Vertex n with birth greater than k, the number of v with birth greater than k and Oriented n v u is at most 3·2^(n−k−1). The count is bounded by the actual graph degree and then by the proved birth-degree estimate.", DescribeRole.Theorem),
            Node("adjacency", "Ordinary adjacency over the reals",
                "adjacency n is exactly (graph n).adjMatrix over the real numbers. Its entries are one at edges and zero elsewhere; there is no weighting, normalization, Laplacian substitution or randomness.", DescribeRole.Definition),
            Node("LateVertex", "The actual later vertex type",
                "LateVertex k t is the subtype of Vertex (k+t) consisting of vertices w with k < birth (k+t) w. The complementary old subtype is identified with Vertex k by the proved canonical-inclusion characterization.", DescribeRole.Definition),
            Node("cutoffEquiv", "The exact old and late partition",
                "For every fixed cutoff k and natural t, cutoffEquiv identifies Vertex k ⊕ LateVertex k t with Vertex (k+t). Its old branch is embed k t and its late branch is subtype inclusion. Injectivity uses preserved births; surjectivity uses the old-vertex characterization. Every actual graph vertex occurs exactly once.", DescribeRole.Definition),
            Node("cutoffBlock", "The old-to-late adjacency block",
                "For k,t natural, cutoffBlock k t is the rectangular real matrix with rows u in Vertex k and columns w in LateVertex k t. Its entry is adjacency (k+t) (embed k t u) w.val. The two index sets can have different cardinalities.", DescribeRole.Definition),
            Node("lateAdjacency", "The actual late induced adjacency",
                "lateAdjacency k t restricts the ordinary real adjacency of stage k+t to LateVertex k t in both coordinates. It is the remainder block C in the fixed-cutoff proof.", DescribeRole.Definition),
            Node("cutoff_adjacency", "Exact adjacency block decomposition",
                "For all k,t and all vertices u,v of Vertex k ⊕ LateVertex k t, adjacency (k+t) evaluated at cutoffEquiv u and cutoffEquiv v equals the corresponding entry of the block matrix [[adjacency k, cutoffBlock k t], [transpose (cutoffBlock k t), lateAdjacency k t]]. Old-old equality is exact edge persistence, mixed equality is the definition of the incidence block and symmetry, and late-late equality is restriction. This is an exact change of vertex coordinates, with no spectral estimate assumed.", DescribeRole.Theorem),
            Node("cutoff_gram_diag", "Exact Gram diagonal",
                "For all k,t natural and u in Vertex k, the u,u entry of cutoffBlock k t times its transpose is the real cast of (graph (k+t)).degree (embed k t u) − (graph k).degree u, with subtraction in Nat. The decomposition of degree into old and late neighbours proves that this subtraction is the intended nonnegative degree increment.", DescribeRole.Theorem),
            Node("cutoff_gram_offdiag", "Common-neighbour estimate for the actual Gram matrix",
                "For all k,t natural and distinct u,v in Vertex k, the u,v entry of B Bᵀ, where B=cutoffBlock k t, is nonnegative and at most 2t over the reals. If u,v are not adjacent at stage k, this entry is zero. Each new common neighbour is the centre of a face containing both old vertices; there are at most two such current inner faces, and no later old-old edge appears.", DescribeRole.Theorem),
            Node("secondIndex", "The second spectral index",
                "For every natural n, secondIndex n is index one in Fin (card (Vertex n)). The proved lower bound four supplies its strict bound. Indices are zero based.", DescribeRole.Definition),
            Node("secondEigenvalue", "The ordinary ordered second eigenvalue",
                "For every natural n, secondEigenvalue n is Mathlib’s decreasing real Hermitian eigenvalues₀ list for (graph n).adjMatrix over the reals, evaluated at secondIndex n. The imported ordered-spectrum API counts eigenvalues with their characteristic-polynomial multiplicities. It uses the actual simple graph and ordinary adjacency.", DescribeRole.Definition),
            Node("limitClaim", "The exact spectral target",
                "limitClaim is Tendsto, along all natural n tending to infinity, of secondEigenvalue n divided by the real power 2^((n:Real)/2), to sqrt(2). The real exponent preserves odd stages. This declaration defines the original target; SecondEigenvalueLimit.result proves it from the actual graph and its cutoff spectral estimates.", DescribeRole.Definition))));

    private static DocumentBlock Node(string name, string title, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("apollonian-" + name.ToLowerInvariant().Replace("_", "-")),
            DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(Source), Blocks(Paragraph(Text(prose))), role);
}
